window.CLO_SEARCH_INDEX=[{"page":"chapter-01/index.html","ordinal":12,"anchor":"search-entry-12","zh":"第一章｜从基础设置开始，认识 CLO3D 工作界面、3D 视角操作与二维、三维、缝纫工具。配合实机截图和录屏逐步练习。","en":"Chapter 01 — Learn basic settings, the CLO workspace, 3D view navigation, and essential 2D, 3D, and sewing tools.","headingZh":"CLO3D 第一章","headingEn":"CLO3D Chapter 01"},{"page":"chapter-01/index.html","ordinal":15,"anchor":"search-entry-15","zh":"一些基础设置","en":"Basic settings","headingZh":"一些基础设置","headingEn":"Basic settings"},{"page":"chapter-01/index.html","ordinal":16,"anchor":"search-entry-16","zh":"正式操作前，先学会切换界面语言，并记住工具栏或工作窗口消失时的恢复方法。以下截图来自本机 CLO 中文界面。","en":"Before you begin, learn how to change the interface language and restore a missing toolbar or work window. The screenshots show CLO in Chinese on this computer.","headingZh":"一些基础设置","headingEn":"Basic settings"},{"page":"chapter-01/index.html","ordinal":17,"anchor":"search-entry-17","zh":"如何更改语言","en":"Change the interface language","headingZh":"如何更改语言","headingEn":"Change the interface language"},{"page":"chapter-01/index.html","ordinal":18,"anchor":"search-entry-18","zh":"点击顶部菜单「设置」→「语言」，再选择需要的语言。选好后退出并重新启动 CLO，界面语言才会切换。","en":"From the top menu, choose Settings → Language, then select the language you want. Quit and restart CLO for the interface language to change.","headingZh":"如何更改语言","headingEn":"Change the interface language"},{"page":"chapter-01/index.html","ordinal":19,"anchor":"search-entry-19","zh":"图 1｜设置 → 语言；更改后需要重启 CLO","en":"Figure 1 | Settings → Language; restart CLO after changing it","headingZh":"如何更改语言","headingEn":"Change the interface language"},{"page":"chapter-01/index.html","ordinal":20,"anchor":"search-entry-20","zh":"找回工具栏与工作窗口","en":"Restore toolbars and work windows","headingZh":"找回工具栏与工作窗口","headingEn":"Restore toolbars and work windows"},{"page":"chapter-01/index.html","ordinal":21,"anchor":"search-entry-21","zh":"如果工具栏不见了，点击顶部「设置」→「显示」，进入「3D 工具栏」或「2D 工具栏」的子菜单，开启需要的工具栏。","en":"If a toolbar disappears, open Settings → Display from the top menu. Use the 3D Toolbar or 2D Toolbar submenu to show the toolbar you need.","headingZh":"找回工具栏与工作窗口","headingEn":"Restore toolbars and work windows"},{"page":"chapter-01/index.html","ordinal":22,"anchor":"search-entry-22","zh":"如果 3D 或 2D 工作窗口不见了，继续进入「窗口」，勾选「3D 视窗」或「2D 板片视窗」。如果整个布局乱了，可点击该菜单底部的「重置画面」。","en":"If the 3D or 2D work window disappears, open Window and enable 3D Window or 2D Pattern Window. If the entire layout is misplaced, choose Reset Screen at the bottom of this menu.","headingZh":"找回工具栏与工作窗口","headingEn":"Restore toolbars and work windows"},{"page":"chapter-01/index.html","ordinal":23,"anchor":"search-entry-23","zh":"图 2｜设置 → 显示 → 窗口；底部可重置画面","en":"Figure 2 | Settings → Display → Window; Reset Screen is at the bottom","headingZh":"找回工具栏与工作窗口","headingEn":"Restore toolbars and work windows"},{"page":"chapter-01/index.html","ordinal":24,"anchor":"search-entry-24","zh":"认识工作界面","en":"Explore the interface","headingZh":"认识工作界面","headingEn":"Explore the interface"},{"page":"chapter-01/index.html","ordinal":25,"anchor":"search-entry-25","zh":"CLO3D 的工作主要在 3D 窗口和 2D 版片窗口之间进行。资源库、对象列表和属性编辑器分布在两侧。先认清各区域，再开始画版。","en":"Most CLO3D work moves between the 3D Garment Window and the 2D Pattern Window. The Library, object list, and Property Editor sit around them. Locate these areas before you draw patterns.","headingZh":"认识工作界面","headingEn":"Explore the interface"},{"page":"chapter-01/index.html","ordinal":26,"anchor":"search-entry-26","zh":"图 1｜本机 CLO 2025 的真实工作界面。点击图片可以放大查看。","en":"Figure 1 | The actual CLO 2025 workspace on this computer. Click to view full size.","headingZh":"认识工作界面","headingEn":"Explore the interface"},{"page":"chapter-01/index.html","ordinal":31,"anchor":"search-entry-31","zh":"如何添加虚拟数字模特","en":"How to add a virtual avatar","headingZh":"如何添加虚拟数字模特","headingEn":"How to add a virtual avatar"},{"page":"chapter-01/index.html","ordinal":32,"anchor":"search-entry-32","zh":"先在 3D 窗口加入模特，再围绕模特安排版片。下面四步使用本机 CLO 2025 的真实操作截图。","en":"Add an avatar to the 3D window before arranging pattern pieces around it. The four steps below use actual CLO 2025 screenshots.","headingZh":"如何添加虚拟数字模特","headingEn":"How to add a virtual avatar"},{"page":"chapter-01/index.html","ordinal":33,"anchor":"search-entry-33","zh":"打开添加模特的菜单","en":"Open the Add Avatar menu","headingZh":"打开添加模特的菜单","headingEn":"Open the Add Avatar menu"},{"page":"chapter-01/index.html","ordinal":34,"anchor":"search-entry-34","zh":"在顶部菜单依次点击「文件」→「增加」→「虚拟模特」。此时会打开模特文件选择窗口。","en":"From the top menu, choose File → Add → Avatar. The avatar file picker will open.","headingZh":"打开添加模特的菜单","headingEn":"Open the Add Avatar menu"},{"page":"chapter-01/index.html","ordinal":35,"anchor":"search-entry-35","zh":"图 2｜文件 → 增加 → 虚拟模特","en":"Figure 2 | File → Add → Avatar","headingZh":"打开添加模特的菜单","headingEn":"Open the Add Avatar menu"},{"page":"chapter-01/index.html","ordinal":36,"anchor":"search-entry-36","zh":"选择需要的模特类型","en":"Choose an avatar category","headingZh":"选择需要的模特类型","headingEn":"Choose an avatar category"},{"page":"chapter-01/index.html","ordinal":37,"anchor":"search-entry-37","zh":"在 Avatar 文件夹中选择想要的类别，例如 Female、Male、Kid 或 Mannequin。不同电脑的 CLO 版本、安装资源和文件夹内容可能不同，以自己看到的文件为准。","en":"In the Avatar folder, choose a category such as Female, Male, Kid, or Mannequin. Folder names and available files can vary with the CLO version and installed assets.","headingZh":"选择需要的模特类型","headingEn":"Choose an avatar category"},{"page":"chapter-01/index.html","ordinal":38,"anchor":"search-entry-38","zh":"图 3｜选择一个模特类别；文件夹内容因电脑而异","en":"Figure 3 | Choose a category; folders vary by computer","headingZh":"选择需要的模特类型","headingEn":"Choose an avatar category"},{"page":"chapter-01/index.html","ordinal":39,"anchor":"search-entry-39","zh":"打开 .avt 模特文件","en":"Open an .avt avatar file","headingZh":"打开 .avt 模特文件","headingEn":"Open an .avt avatar file"},{"page":"chapter-01/index.html","ordinal":40,"anchor":"search-entry-40","zh":"进入所选类别后，找到扩展名为 .avt 的模特文件。图中 FV2.1_Mia.avt 只是示例；双击你想用的 .avt 文件，或选中后点击「打开」。","en":"Inside the chosen category, find a file ending in .avt. FV2.1_Mia.avt is only an example; double-click your chosen file or select it and click Open.","headingZh":"打开 .avt 模特文件","headingEn":"Open an .avt avatar file"},{"page":"chapter-01/index.html","ordinal":41,"anchor":"search-entry-41","zh":"图 4｜选择扩展名为 .avt 的文件","en":"Figure 4 | Open a file ending in .avt","headingZh":"打开 .avt 模特文件","headingEn":"Open an .avt avatar file"},{"page":"chapter-01/index.html","ordinal":42,"anchor":"search-entry-42","zh":"确认模特加载成功","en":"Check the loaded avatar","headingZh":"确认模特加载成功","headingEn":"Check the loaded avatar"},{"page":"chapter-01/index.html","ordinal":43,"anchor":"search-entry-43","zh":"返回 CLO 的 3D 窗口。看到模特出现在工作区，就说明添加成功；图中展示的是其中一个女性模特。","en":"Return to CLO's 3D window. The avatar appearing in the workspace confirms that it loaded successfully. The picture shows one example female avatar.","headingZh":"确认模特加载成功","headingEn":"Check the loaded avatar"},{"page":"chapter-01/index.html","ordinal":44,"anchor":"search-entry-44","zh":"图 5｜模特出现在 3D 窗口中","en":"Figure 5 | The avatar appears in the 3D window","headingZh":"确认模特加载成功","headingEn":"Check the loaded avatar"},{"page":"chapter-01/index.html","ordinal":45,"anchor":"search-entry-45","zh":"鼠标与视角操作","en":"Mouse and view controls","headingZh":"鼠标与视角操作","headingEn":"Mouse and view controls"},{"page":"chapter-01/index.html","ordinal":46,"anchor":"search-entry-46","zh":"在 3D 窗口中，先学会移动观察视角，再开始摆放版片。下面四段录屏分别演示平移、旋转、缩放和数字键切换视角；播放时可以暂停并跟着操作。","en":"Learn to navigate the 3D window before placing pattern pieces. These four recordings show panning, rotating, zooming, and switching views with number keys. Pause each clip and practice along.","headingZh":"鼠标与视角操作","headingEn":"Mouse and view controls"},{"page":"chapter-01/index.html","ordinal":47,"anchor":"search-entry-47","zh":"平移视角","en":"Pan the view","headingZh":"平移视角","headingEn":"Pan the view"},{"page":"chapter-01/index.html","ordinal":48,"anchor":"search-entry-48","zh":"按住鼠标滚轮（中键），上下拖动鼠标，就能平移 3D 画面。这个操作需要可按下的滚轮；Apple Magic Mouse 没有中键，不能直接使用此按法。","en":"Hold down the mouse wheel (middle button) and drag up or down to pan the 3D view. This requires a clickable wheel; the Apple Magic Mouse has no middle button.","headingZh":"平移视角","headingEn":"Pan the view"},{"page":"chapter-01/index.html","ordinal":50,"anchor":"search-entry-50","zh":"旋转视角","en":"Rotate the view","headingZh":"旋转视角","headingEn":"Rotate the view"},{"page":"chapter-01/index.html","ordinal":51,"anchor":"search-entry-51","zh":"按住鼠标右键并拖动鼠标，视角会围绕世界中心旋转。试着从模特正面转到侧面，再转回来。","en":"Hold the right mouse button and drag to rotate the view around the world center. Try turning from the avatar's front to its side and back.","headingZh":"旋转视角","headingEn":"Rotate the view"},{"page":"chapter-01/index.html","ordinal":53,"anchor":"search-entry-53","zh":"缩放画面","en":"Zoom the view","headingZh":"缩放画面","headingEn":"Zoom the view"},{"page":"chapter-01/index.html","ordinal":54,"anchor":"search-entry-54","zh":"滚动鼠标滚轮，可以放大或缩小 3D 画面。缩放以画面中心为基准；模特偏离中心时，先平移视角再缩放。","en":"Scroll the mouse wheel to zoom in or out. Zooming uses the center of the screen, so pan first if the avatar is off center.","headingZh":"缩放画面","headingEn":"Zoom the view"},{"page":"chapter-01/index.html","ordinal":56,"anchor":"search-entry-56","zh":"数字键切换视角","en":"Switch views with number keys","headingZh":"数字键切换视角","headingEn":"Switch views with number keys"},{"page":"chapter-01/index.html","ordinal":57,"anchor":"search-entry-57","zh":"按数字键 1–6，可以快速切换预设视角；按 2 可回到模特正面。","en":"Press number keys 1–6 to switch between preset views. Key 2 returns to the avatar’s front view.","headingZh":"数字键切换视角","headingEn":"Switch views with number keys"},{"page":"chapter-01/index.html","ordinal":58,"anchor":"search-entry-58","zh":"如果 3D 窗口里突然看不到物体，或旋转后找不到方向，先用这些数字键找回熟悉的观察角度。","en":"If an object disappears from view or you lose your orientation, use these keys to return to a familiar angle.","headingZh":"数字键切换视角","headingEn":"Switch views with number keys"},{"page":"chapter-01/index.html","ordinal":60,"anchor":"search-entry-60","zh":"二维版片工具","en":"Essential 2D pattern tools","headingZh":"二维版片工具","headingEn":"Essential 2D pattern tools"},{"page":"chapter-01/index.html","ordinal":61,"anchor":"search-entry-61","zh":"先认清真实图标或菜单位置，再跟着录屏操作。本章已加入整片调整、点线编辑、曲线与加点演示；其他工具保留本机 CLO 2025.0.128 中文菜单截图。","en":"Identify each tool from its actual CLO icon or menu capture, then follow the recordings. This chapter now includes demonstrations of whole-pattern moves, point-and-line edits, curves, and added points. Other tools retain menu captures from CLO 2025.0.128 in Chinese.","headingZh":"二维版片工具","headingEn":"Essential 2D pattern tools"},{"page":"chapter-01/index.html","ordinal":62,"anchor":"search-entry-62","zh":"先认识二维版片窗口","en":"First, locate the 2D Pattern Window","headingZh":"先认识二维版片窗口","headingEn":"First, locate the 2D Pattern Window"},{"page":"chapter-01/index.html","ordinal":63,"anchor":"search-entry-63","zh":"画版之前，先认清二维窗口里的两个位置：右侧工具栏，以及中央的模特剪影。点击图片可以放大查看。","en":"Before drafting, find two landmarks in the 2D window: the toolbar on the right and the avatar silhouette in the center. Click either image to enlarge it.","headingZh":"先认识二维版片窗口","headingEn":"First, locate the 2D Pattern Window"},{"page":"chapter-01/index.html","ordinal":64,"anchor":"search-entry-64","zh":"图 1｜二维版片工具栏","en":"Figure 1 | 2D pattern toolbar","headingZh":"先认识二维版片窗口","headingEn":"First, locate the 2D Pattern Window"},{"page":"chapter-01/index.html","ordinal":66,"anchor":"search-entry-66","zh":"图 2｜与模特同步的剪影","en":"Figure 2 | Avatar silhouette","headingZh":"先认识二维版片窗口","headingEn":"First, locate the 2D Pattern Window"},{"page":"chapter-01/index.html","ordinal":68,"anchor":"search-entry-68","zh":"读懂工具图标，画出第一块版片","en":"Read the tool icons and draw your first pattern","headingZh":"读懂工具图标，画出第一块版片","headingEn":"Read the tool icons and draw your first pattern"},{"page":"chapter-01/index.html","ordinal":69,"anchor":"search-entry-69","zh":"先学会展开工具组，再跟着视频画一个矩形。","en":"First, learn to expand a tool group. Then follow the video to draw a rectangle.","headingZh":"读懂工具图标，画出第一块版片","headingEn":"Read the tool icons and draw your first pattern"},{"page":"chapter-01/index.html","ordinal":70,"anchor":"search-entry-70","zh":"图 1｜小三角表示还有其他工具","en":"Figure 1 | The triangle marks a tool group","headingZh":"读懂工具图标，画出第一块版片","headingEn":"Read the tool icons and draw your first pattern"},{"page":"chapter-01/index.html","ordinal":72,"anchor":"search-entry-72","zh":"图 2｜长按后展开小菜单","en":"Figure 2 | The expanded tool menu","headingZh":"读懂工具图标，画出第一块版片","headingEn":"Read the tool icons and draw your first pattern"},{"page":"chapter-01/index.html","ordinal":74,"anchor":"search-entry-74","zh":"跟着视频创建矩形","en":"Draw a rectangle with the video","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":75,"anchor":"search-entry-75","zh":"录屏同时显示左侧 3D 窗口和右侧 2D 窗口。可以暂停或全屏播放，边看边做。","en":"The recording shows the 3D window on the left and the 2D window on the right. Pause or use full screen while you follow along.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":76,"anchor":"search-entry-76","zh":"在 2D 窗口右侧工具栏，按住绘图工具图标，展开包含「多边形」「矩形」等选项的小菜单，然后点击「矩形」。","en":"In the 2D toolbar, press and hold the shape tool to open its menu, then choose Rectangle.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":77,"anchor":"search-entry-77","zh":"在 2D 工作区选定起点，按住鼠标左键向右下方拖动；松开鼠标，矩形版片就创建好了。","en":"Choose a starting point in the 2D workspace. Hold the left mouse button and drag down and right, then release to create the rectangular pattern.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":78,"anchor":"search-entry-78","zh":"看向左侧 3D 窗口：同一块矩形版片会出现在模特附近。录屏最后还旋转了视角，从侧面查看版片。","en":"Look at the 3D window on the left: the same rectangular pattern appears near the avatar. At the end, the view rotates to show the piece from the side.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":79,"anchor":"search-entry-79","zh":"打开绘图工具组，选择矩形，在二维工作区拖动画出版片","en":"Open the shape tools, choose Rectangle, and drag in the 2D workspace","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":80,"anchor":"search-entry-80","zh":"观察 2D 与 3D 的对应关系","en":"Notice how the 2D and 3D views correspond","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":81,"anchor":"search-entry-81","zh":"矩形在右侧 2D 工作区生成的同时，也会在左侧 3D 窗口出现。它在 2D 中相对模特剪影的摆放位置，对应着 3D 中相对模特的位置；从不同角度看，版片的外观会因透视而变化。","en":"The rectangle appears in the 3D window as soon as it is created in 2D. Its placement relative to the 2D avatar silhouette corresponds to its position around the 3D avatar. Perspective can make the piece look different from another viewing angle.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":82,"anchor":"search-entry-82","zh":"先分清：整片，还是点和线？","en":"First choose: whole piece, or points and lines?","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":83,"anchor":"search-entry-83","zh":"「调整板片」（A）选择并移动整块版片；「编辑板片」（Z）只调整选中的点或线，改变局部轮廓。","en":"Transform Pattern (A) selects and moves the whole piece. Edit Pattern (Z) changes selected points or lines to reshape its outline.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":86,"anchor":"search-entry-86","zh":"调整板片","en":"Transform Pattern","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":88,"anchor":"search-entry-88","zh":"Transform Pattern","en":"Transform Pattern","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":89,"anchor":"search-entry-89","zh":"2D → 编辑 → 调整板片","en":"2D → Edit → Transform Pattern","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":90,"anchor":"search-entry-90","zh":"选中整块版片，整体移动、旋转或缩放；不单独改变某个点或一条边。","en":"Select the whole pattern to move, rotate, or scale it without editing an individual point or edge.","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":91,"anchor":"search-entry-91","zh":"按 A，点击版片内部；整片高亮，周围出现选框。","en":"Press A and click inside the pattern. The whole piece highlights and a bounding box appears.","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":92,"anchor":"search-entry-92","zh":"按住鼠标左键拖动，整块版片一起移动，原来的矩形轮廓不变。","en":"Hold the left mouse button and drag. The whole piece moves without changing its rectangular outline.","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":93,"anchor":"search-entry-93","zh":"只想修改一个角点或一条边？改用「编辑板片」（Z）。","en":"To change one corner or edge, use Edit Pattern (Z).","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":97,"anchor":"search-entry-97","zh":"编辑板片","en":"Edit Pattern","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":99,"anchor":"search-entry-99","zh":"Edit Pattern","en":"Edit Pattern","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":100,"anchor":"search-entry-100","zh":"2D → 编辑 → 编辑板片","en":"2D → Edit → Edit Pattern","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":101,"anchor":"search-entry-101","zh":"选择版片轮廓上的点或线。选中后目标会高亮，拖动它就能改变局部形状。","en":"Select a point or line on the pattern outline. The selection highlights; drag it to reshape that part of the pattern.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":102,"anchor":"search-entry-102","zh":"按 Z，点击一个角点；高亮后拖动，只改变这个角的位置。","en":"Press Z and click a corner point. Once highlighted, drag it to move that corner.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":103,"anchor":"search-entry-103","zh":"也可以点击一条边；边线高亮后拖动，调整这段轮廓。","en":"You can also click an edge. Drag the highlighted line to adjust that part of the outline.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":104,"anchor":"search-entry-104","zh":"需要精确数值时，选中目标并开始拖动；拖动过程中按鼠标右键，再输入需要的数值。","en":"For an exact value, start dragging the selected point or line, then press the right mouse button while dragging and enter the value.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":106,"anchor":"search-entry-106","zh":"V、C、X：三个不同的动作","en":"V, C, X: three different actions","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":107,"anchor":"search-entry-107","zh":"V 在线段上拖出曲线点；C 直接拖动一段线或弧线；X 在边线上添加新点。它们都从右侧编辑工具的小菜单中选择。","en":"V pulls a curve point from a segment; C drags a line or arc to change its bend; X adds a new point on an edge. All three are in the editing-tool flyout.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":110,"anchor":"search-entry-110","zh":"编辑曲线点","en":"Edit Curve Point","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":112,"anchor":"search-entry-112","zh":"Edit Curve Point","en":"Edit Curve Point","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":113,"anchor":"search-entry-113","zh":"2D → 编辑 → 编辑曲线点","en":"2D → Edit → Edit Curve Point","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":114,"anchor":"search-entry-114","zh":"只在线段上操作。拖动线上的曲线点，可将直边拉成弧线，并控制弧线形状。","en":"Work on a pattern edge: drag a curve point on the segment to bend a straight edge into a curve and shape the arc.","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":115,"anchor":"search-entry-115","zh":"长按右侧的编辑工具图标，在小菜单中选择「编辑曲线点」（V）。","en":"Press and hold the editing-tool icon on the right, then choose Edit Curve Point (V) from its flyout.","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":116,"anchor":"search-entry-116","zh":"将鼠标移到要弯曲的线段。看到红色提示点后，按住左键向外拖动；蓝色预览线显示弧度，松开后曲线成形。","en":"Move over the segment until a red guide point appears. Hold the left button and drag outward; the blue preview shows the bend. Release to finish the curve.","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":117,"anchor":"search-entry-117","zh":"此工具作用于版片的边线，不能在版片内部直接拉出曲线。","en":"This tool works on the pattern edge; it does not draw a curve inside the piece.","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":120,"anchor":"search-entry-120","zh":"编辑圆弧","en":"Edit Curvature","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":122,"anchor":"search-entry-122","zh":"Edit Curvature","en":"Edit Curvature","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":123,"anchor":"search-entry-123","zh":"2D → 编辑 → 编辑圆弧","en":"2D → Edit → Edit Curvature","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":124,"anchor":"search-entry-124","zh":"直接拖动一段线或已有弧线，快速改变整段的弯曲程度。","en":"Drag a segment or an existing arc to change the bend of that whole section quickly.","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":125,"anchor":"search-entry-125","zh":"长按编辑工具图标，在小菜单中选择「编辑圆弧」（C）。","en":"Press and hold the editing-tool icon, then choose Edit Curvature (C) from its flyout.","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":126,"anchor":"search-entry-126","zh":"将鼠标放在线段或弧线上，按住左键向内或向外拖动；观察轮廓变化，松开鼠标完成调整。","en":"Place the pointer on a line or arc and drag inward or outward. Watch the outline change, then release to finish.","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":127,"anchor":"search-entry-127","zh":"视频先把右侧边线拉成弧线，再调整顶部已有的弧线。","en":"The video first bends the right edge, then adjusts the existing arc at the top.","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":131,"anchor":"search-entry-131","zh":"加点／分线","en":"Add Point / Split Line","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":133,"anchor":"search-entry-133","zh":"Add Point / Split Line","en":"Add Point / Split Line","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":134,"anchor":"search-entry-134","zh":"2D → 编辑 → 加点／分线","en":"2D → Edit → Add Point / Split Line","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":135,"anchor":"search-entry-135","zh":"在版片边线上添加新点，把原线段分成更短的段，方便后续局部编辑。","en":"Add a new point to a pattern edge, dividing the original segment into shorter sections for later editing.","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":136,"anchor":"search-entry-136","zh":"长按编辑工具图标，在小菜单中选择「加点／分线」（X）。","en":"Press and hold the editing-tool icon, then choose Add Point / Split Line (X) from its flyout.","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":137,"anchor":"search-entry-137","zh":"在需要加点的直线或曲线上单击。新点会出现在点击处；视频中沿右侧边线连续添加了几个点。","en":"Click a straight or curved edge where you want a point. A new point appears there; the video adds several along the right edge.","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":138,"anchor":"search-entry-138","zh":"加点会分割边线，不会把整块版片切成两块。","en":"Adding points divides the edge, not the pattern piece itself.","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":141,"anchor":"search-entry-141","zh":"删除板片","en":"Delete a Pattern","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":143,"anchor":"search-entry-143","zh":"Delete a Pattern","en":"Delete a Pattern","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":144,"anchor":"search-entry-144","zh":"2D 窗口 → 选中版片 → Delete","en":"2D window → Select pattern → Delete","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":145,"anchor":"search-entry-145","zh":"删除不需要的整块版片。先确认整片已被选中，再按键盘上的 Delete 键。","en":"Remove an unwanted pattern piece. Select the whole piece first, then press Delete on the keyboard.","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":146,"anchor":"search-entry-146","zh":"使用「调整板片」（A），点击版片内部；看到蓝色轮廓和选框，表示整片已选中。","en":"Use Transform Pattern (A) and click inside the piece. A blue outline and bounding box show that the whole pattern is selected.","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":147,"anchor":"search-entry-147","zh":"按 Delete。版片从 2D 窗口消失；如果误删，可立即按 Ctrl+Z 撤销。","en":"Press Delete. The pattern disappears from the 2D window. If it was a mistake, press Ctrl+Z to undo.","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":148,"anchor":"search-entry-148","zh":"视频中的按键写作 Delete，常缩写为 Del。","en":"The key is spelled Delete and is often abbreviated Del.","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":151,"anchor":"search-entry-151","zh":"创建矩形版片","en":"Create a Rectangle Pattern","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":153,"anchor":"search-entry-153","zh":"Rectangle","en":"Rectangle","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":154,"anchor":"search-entry-154","zh":"2D → 图形工具组 → 矩形","en":"2D → Shape tools → Rectangle","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":155,"anchor":"search-entry-155","zh":"从图形工具组选择「矩形」，在二维工作区画出一块矩形版片。","en":"Choose Rectangle from the shape-tool group and draw a rectangular pattern in the 2D workspace.","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":156,"anchor":"search-entry-156","zh":"长按 2D 窗口右侧的图形工具图标，在展开的小菜单中选择「矩形」（S）；也可以直接按 S。","en":"Press and hold the shape-tool icon on the right of the 2D window, then choose Rectangle (S) from the flyout. You can also press S.","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":157,"anchor":"search-entry-157","zh":"在工作区确定第一个角，向对角方向移动鼠标并完成绘制；白色矩形和四个角点出现后，版片就创建好了。","en":"Choose the first corner in the workspace, move toward the opposite corner, and complete the shape. The white rectangle and its four corner points show that the pattern has been created.","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":158,"anchor":"search-entry-158","zh":"图形工具组还包括多边形、圆形等工具；右下角的小三角表示可以长按展开。","en":"The same tool group also includes Polygon and Ellipse. The small triangle means you can press and hold to open the group.","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":162,"anchor":"search-entry-162","zh":"多边形","en":"Polygon","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":163,"anchor":"search-entry-163","zh":"Polygon","en":"Polygon","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":164,"anchor":"search-entry-164","zh":"2D → 生成 → 多边形","en":"2D → Create → Polygon","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":165,"anchor":"search-entry-165","zh":"逐点绘制自由轮廓的版片。","en":"Build a custom pattern outline point by point.","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":166,"anchor":"search-entry-166","zh":"按 H，在二维窗口依次单击各个转角。","en":"Press H and click each corner in the 2D window.","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":167,"anchor":"search-entry-167","zh":"最后单击起点，闭合轮廓并生成版片。","en":"Click the starting point again to close the pattern.","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":168,"anchor":"search-entry-168","zh":"先练习四边形；没有闭合的轮廓还不是完成的版片。","en":"Start with four corners and make sure the outline is closed.","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":172,"anchor":"search-entry-172","zh":"圆形","en":"Ellipse","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":173,"anchor":"search-entry-173","zh":"Ellipse","en":"Ellipse","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":174,"anchor":"search-entry-174","zh":"2D → 生成 → 圆形","en":"2D → Create → Ellipse","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":175,"anchor":"search-entry-175","zh":"创建椭圆或圆形版片。此中文版本菜单显示「圆形」。","en":"Create ellipses or circles. This Chinese interface labels the tool 圆形.","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":176,"anchor":"search-entry-176","zh":"按 E，在二维窗口按住左键拖动。","en":"Press E and click-drag in the 2D window.","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":177,"anchor":"search-entry-177","zh":"松开完成椭圆；按住 Shift 拖动可创建正圆。","en":"Release for an ellipse; hold Shift while dragging for a circle.","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":178,"anchor":"search-entry-178","zh":"单击空白处可以打开尺寸输入窗口。","en":"Click once in empty space to open the size dialog.","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":180,"anchor":"search-entry-180","zh":"内部形状：绘制、切断与镂空","en":"Internal Shapes: Draw, Cut & Make a Hole","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":181,"anchor":"search-entry-181","zh":"Internal Shapes","en":"Internal Shapes","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":182,"anchor":"search-entry-182","zh":"2D → 右侧内部形状工具组","en":"2D → Internal-shape tool group on the right","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":183,"anchor":"search-entry-183","zh":"长按这个图标可展开内部形状工具组。下面以「内部矩形」为例；同组还有「内部多边形／线」（G）等工具。","en":"Press and hold this icon to open the internal-shape tools. The lesson uses Internal Rectangle; the group also includes Internal Polygon / Line (G).","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":184,"anchor":"search-entry-184","zh":"内部形状只能画在已有版片内。未选中时，内部线显示为红色；选中后会高亮，也可以用编辑工具调整点和线。单纯画出内部形状，并不会立刻切开版片。","en":"Internal shapes can only be drawn inside an existing pattern. Their lines appear red when unselected and highlight when selected. You can edit their points and edges with an editing tool. Drawing an internal shape alone does not cut the pattern.","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":185,"anchor":"search-entry-185","zh":"添加并编辑内部形状","en":"Draw and edit an internal shape","headingZh":"添加并编辑内部形状","headingEn":"Draw and edit an internal shape"},{"page":"chapter-01/index.html","ordinal":186,"anchor":"search-entry-186","zh":"在版片内部选择「内部矩形」，确定两个对角位置，画出闭合轮廓。","en":"Choose Internal Rectangle and set two opposite corners inside the pattern to draw a closed outline.","headingZh":"添加并编辑内部形状","headingEn":"Draw and edit an internal shape"},{"page":"chapter-01/index.html","ordinal":187,"anchor":"search-entry-187","zh":"切换到编辑工具，选中内部线的点或边并拖动，调整形状。","en":"Switch to an editing tool, then select and drag a point or edge to reshape the outline.","headingZh":"添加并编辑内部形状","headingEn":"Draw and edit an internal shape"},{"page":"chapter-01/index.html","ordinal":188,"anchor":"search-entry-188","zh":"切断：得到两块裁片","en":"Cut: create two pattern pieces","headingZh":"切断：得到两块裁片","headingEn":"Cut: create two pattern pieces"},{"page":"chapter-01/index.html","ordinal":189,"anchor":"search-entry-189","zh":"选中闭合的内部形状，右键选择「切断」。","en":"Select the closed internal shape, right-click, and choose Cut.","headingZh":"切断：得到两块裁片","headingEn":"Cut: create two pattern pieces"},{"page":"chapter-01/index.html","ordinal":190,"anchor":"search-entry-190","zh":"CLO 沿轮廓把原版片分成外侧和内侧裁片；两块都可以单独移动。","en":"CLO splits the original pattern into outer and inner pieces along the outline. You can move each piece separately.","headingZh":"切断：得到两块裁片","headingEn":"Cut: create two pattern pieces"},{"page":"chapter-01/index.html","ordinal":191,"anchor":"search-entry-191","zh":"转化为洞：留下镂空","en":"Convert to Hole: make a cutout","headingZh":"转化为洞：留下镂空","headingEn":"Convert to Hole: make a cutout"},{"page":"chapter-01/index.html","ordinal":192,"anchor":"search-entry-192","zh":"选中闭合的内部形状，右键选择「转化为洞」。","en":"Select the closed internal shape, right-click, and choose Convert to Hole.","headingZh":"转化为洞：留下镂空","headingEn":"Convert to Hole: make a cutout"},{"page":"chapter-01/index.html","ordinal":193,"anchor":"search-entry-193","zh":"内部区域变成透明开口，原版片保留外框；不会另外生成内侧裁片。","en":"The enclosed area becomes a transparent opening. The outer pattern remains, and no separate inner piece is created.","headingZh":"转化为洞：留下镂空","headingEn":"Convert to Hole: make a cutout"},{"page":"chapter-01/index.html","ordinal":194,"anchor":"search-entry-194","zh":"记住区别：切断会得到内外两块可分别移动的裁片；转化为洞只在原版片上留下开口。","en":"Remember: Cut creates inner and outer pieces that can move separately; Convert to Hole leaves an opening in the original pattern.","headingZh":"转化为洞：留下镂空","headingEn":"Convert to Hole: make a cutout"},{"page":"chapter-01/index.html","ordinal":195,"anchor":"search-entry-195","zh":"三维操作与模拟","en":"3D controls & simulation","headingZh":"三维操作与模拟","headingEn":"3D controls & simulation"},{"page":"chapter-01/index.html","ordinal":196,"anchor":"search-entry-196","zh":"先学习用 Gizmo 调整版片，再从模块库添加服装版片、利用模特的安排点快速放置；最后再认识模拟功能。","en":"First use the Gizmo to adjust patterns. Then add ready-made pieces from the Module Library and place them with the avatar’s arrangement points before learning Simulation.","headingZh":"三维操作与模拟","headingEn":"3D controls & simulation"},{"page":"chapter-01/index.html","ordinal":197,"anchor":"search-entry-197","zh":"Gizmo · 三维操纵器","en":"Gizmo · 3D Transform Controls","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":198,"anchor":"search-entry-198","zh":"在 2D 工作区选中一块版片，3D 窗口中的同一块版片也会变成黄色高亮，并出现 Gizmo。它是调整版片位置与方向的控制器。","en":"Select a pattern piece in the 2D workspace. The same piece highlights yellow in the 3D window, and the Gizmo appears. Use it to adjust the piece's position and orientation.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":200,"anchor":"search-entry-200","zh":"黄色高亮＝已选中","en":"Yellow highlight = selected","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":201,"anchor":"search-entry-201","zh":"2D 和 3D 中高亮的是同一块版片；移动或旋转的是版片，不是相机。","en":"The highlighted shape is the same pattern in both windows. The Gizmo transforms the pattern, not the camera.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":202,"anchor":"search-entry-202","zh":"直线箭头＝移动","en":"Straight arrows = move","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":203,"anchor":"search-entry-203","zh":"按住箭头拖动，沿对应方向移动版片。","en":"Drag an arrow to move the piece along that direction.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":204,"anchor":"search-entry-204","zh":"彩色圆环＝旋转","en":"Colored rings = rotate","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":205,"anchor":"search-entry-205","zh":"按住圆环拖动，让版片绕对应轴转动。","en":"Drag a ring to rotate the piece around its corresponding axis.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":206,"anchor":"search-entry-206","zh":"先辨认坐标模式","en":"Check the coordinate mode","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":207,"anchor":"search-entry-207","zh":"如果使用「屏幕坐标／视角」模式，Gizmo 的轴会跟随当前相机视角；它不是固定的世界坐标。斜着看时，屏幕上看似向旁边拖动，换个角度可能发现版片也有前后偏移。调整后从其他视角复查；需要固定空间方向时，可切换到「世界坐标」模式。","en":"In Screen Coordinate mode, the Gizmo axes follow the camera view rather than fixed world axes. From an oblique angle, a drag that looks sideways on screen can leave the piece offset in depth. Check from another view afterward, or switch to World Coordinate mode when you need fixed spatial directions.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":208,"anchor":"search-entry-208","zh":"选中版片，使用 Gizmo 移动与旋转","en":"Select, move, and rotate with the Gizmo","headingZh":"选中版片，使用 Gizmo 移动与旋转","headingEn":"Select, move, and rotate with the Gizmo"},{"page":"chapter-01/index.html","ordinal":209,"anchor":"search-entry-209","zh":"观察右侧 2D 版片被选中后，左侧 3D 版片同步变黄。拖动直线箭头可移动，拖动圆环可旋转。","en":"Watch the 2D selection highlight the same piece in 3D. Drag a straight arrow to move it and a ring to rotate it.","headingZh":"选中版片，使用 Gizmo 移动与旋转","headingEn":"Select, move, and rotate with the Gizmo"},{"page":"chapter-01/index.html","ordinal":210,"anchor":"search-entry-210","zh":"换个视角，检查版片位置","en":"Change view and check placement","headingZh":"换个视角，检查版片位置","headingEn":"Change view and check placement"},{"page":"chapter-01/index.html","ordinal":211,"anchor":"search-entry-211","zh":"先调整观察角度，再从侧面或上方检查版片与模特的距离；改变视角本身不会移动版片。","en":"Adjust the camera angle, then inspect the piece's distance from the avatar from the side or above. Changing the view alone does not move the pattern.","headingZh":"换个视角，检查版片位置","headingEn":"Change view and check placement"},{"page":"chapter-01/index.html","ordinal":212,"anchor":"search-entry-212","zh":"用固定视角更精确地调整","en":"Use fixed views for precise placement","headingZh":"换个视角，检查版片位置","headingEn":"Change view and check placement"},{"page":"chapter-01/index.html","ordinal":213,"anchor":"search-entry-213","zh":"在 3D 窗口按数字键切换视角，再观察并调整版片：","en":"With the 3D window active, press a number key to change views before checking and adjusting the piece:","headingZh":"换个视角，检查版片位置","headingEn":"Change view and check placement"},{"page":"chapter-01/index.html","ordinal":221,"anchor":"search-entry-221","zh":"模块库与安排点 · 快速放置版片","en":"Module Library & Arrangement Points","headingZh":"模块库与安排点 · 快速放置版片","headingEn":"Module Library & Arrangement Points"},{"page":"chapter-01/index.html","ordinal":222,"anchor":"search-entry-222","zh":"先从模块库取用现成服装版片，再显示模特身上的安排点，让版片快速到达合适的位置。","en":"Add ready-made pattern pieces from the Module Library, then use the avatar's arrangement points to place them quickly.","headingZh":"模块库与安排点 · 快速放置版片","headingEn":"Module Library & Arrangement Points"},{"page":"chapter-01/index.html","ordinal":223,"anchor":"search-entry-223","zh":"从模块库添加版片","en":"Add pattern pieces from the Module Library","headingZh":"从模块库添加版片","headingEn":"Add pattern pieces from the Module Library"},{"page":"chapter-01/index.html","ordinal":224,"anchor":"search-entry-224","zh":"点击工作区左侧的「模块库」，打开现成的服装模板。录屏里先进入上衣分类，再打开一组版片；你电脑中的分类和文件可能不同。","en":"Open the Module Library on the left. In the recording, the instructor opens a top template and its pattern pieces; folders and files may differ on your computer.","headingZh":"从模块库添加版片","headingEn":"Add pattern pieces from the Module Library"},{"page":"chapter-01/index.html","ordinal":225,"anchor":"search-entry-225","zh":"双击需要的版片缩略图，把版片加入当前项目。观察 2D 窗口出现版片，3D 窗口也同步出现对应的版片。","en":"Double-click a pattern thumbnail to add it to the current project. The piece appears in both the 2D and 3D windows.","headingZh":"从模块库添加版片","headingEn":"Add pattern pieces from the Module Library"},{"page":"chapter-01/index.html","ordinal":226,"anchor":"search-entry-226","zh":"添加后选中版片，按上一节的方法使用 Gizmo 移动、旋转，并换个视角检查它与模特的距离。","en":"Select the added piece, use the Gizmo from the previous lesson to move or rotate it, and check its distance from the avatar from another view.","headingZh":"从模块库添加版片","headingEn":"Add pattern pieces from the Module Library"},{"page":"chapter-01/index.html","ordinal":227,"anchor":"search-entry-227","zh":"显示安排点，让版片快速就位","en":"Show arrangement points and place a piece","headingZh":"显示安排点，让版片快速就位","headingEn":"Show arrangement points and place a piece"},{"page":"chapter-01/index.html","ordinal":228,"anchor":"search-entry-228","zh":"点击模块库面板右侧的小箭头，将面板收起，留出更多 3D 操作空间。","en":"Click the small arrow at the right edge of the Module Library panel to collapse it and make more room in the 3D window.","headingZh":"显示安排点，让版片快速就位","headingEn":"Show arrangement points and place a piece"},{"page":"chapter-01/index.html","ordinal":229,"anchor":"search-entry-229","zh":"在模特左侧工具栏，长按「虚拟模特信息显示」图标，打开小菜单，选择「显示安排点」（快捷键 Shift+F）。模特周围会出现蓝色安排点。","en":"Long-press the Avatar Information Display icon beside the avatar. In its menu, choose Show Arrangement Points (Shift+F). Blue points appear around the avatar.","headingZh":"显示安排点，让版片快速就位","headingEn":"Show arrangement points and place a piece"},{"page":"chapter-01/index.html","ordinal":230,"anchor":"search-entry-230","zh":"在 2D 或 3D 窗口选中一块版片，再点击模特身上合适的蓝色点。版片会自动移动到该安排位置；随后从正面和侧面检查，并按需用 Gizmo 微调。","en":"Select a piece in either the 2D or 3D window, then click a suitable blue point on the avatar. The piece snaps to that arrangement location. Check it from front and side views and refine with the Gizmo if needed.","headingZh":"显示安排点，让版片快速就位","headingEn":"Show arrangement points and place a piece"},{"page":"chapter-01/index.html","ordinal":232,"anchor":"search-entry-232","zh":"模拟 · 让版片成为服装","en":"Simulation · Turn patterns into a garment","headingZh":"模拟 · 让版片成为服装","headingEn":"Simulation · Turn patterns into a garment"},{"page":"chapter-01/index.html","ordinal":233,"anchor":"search-entry-233","zh":"3D 窗口中，版片之间的彩色线条表示缝纫关系：两块版片的边缘已设为相互连接。启动模拟后，CLO 会计算布料在重力和碰撞下的形状。","en":"Colored lines between pieces in the 3D window show sewing relationships between their edges. When Simulation runs, CLO calculates the fabric's response to gravity and collisions.","headingZh":"模拟 · 让版片成为服装","headingEn":"Simulation · Turn patterns into a garment"},{"page":"chapter-01/index.html","ordinal":234,"anchor":"search-entry-234","zh":"模拟开启时，左侧箭头变蓝","en":"The left arrow turns blue while Simulation runs","headingZh":"模拟 · 让版片成为服装","headingEn":"Simulation · Turn patterns into a garment"},{"page":"chapter-01/index.html","ordinal":235,"anchor":"search-entry-235","zh":"空格键：启动与暂停模拟","en":"Spacebar: start and pause Simulation","headingZh":"空格键：启动与暂停模拟","headingEn":"Spacebar: start and pause Simulation"},{"page":"chapter-01/index.html","ordinal":236,"anchor":"search-entry-236","zh":"按空格键启动模拟，左侧工具栏的模拟箭头会变为蓝色。观察原本分开的版片如何根据缝纫线连接、落到模特身上，逐渐形成服装的垂坠。再次按空格键可暂停模拟。","en":"Press Space to start Simulation. The arrow on the left toolbar turns blue. Watch the separate pieces connect along their sewing lines, settle onto the avatar, and drape as a garment. Press Space again to pause.","headingZh":"空格键：启动与暂停模拟","headingEn":"Spacebar: start and pause Simulation"},{"page":"chapter-01/index.html","ordinal":237,"anchor":"search-entry-237","zh":"拖拽布料，观察实时变化","en":"Drag the fabric and observe its response","headingZh":"拖拽布料，观察实时变化","headingEn":"Drag the fabric and observe its response"},{"page":"chapter-01/index.html","ordinal":238,"anchor":"search-entry-238","zh":"模拟运行时，在 3D 服装上按住鼠标左键并拖动。布料会被拉起或推开，周围的褶皱随之变化；松开鼠标后，布料继续受重力影响重新垂落。","en":"While Simulation is running, hold the left mouse button on the 3D garment and drag. The fabric lifts or shifts and nearby folds change; after release, gravity makes it settle again.","headingZh":"拖拽布料，观察实时变化","headingEn":"Drag the fabric and observe its response"},{"page":"chapter-01/index.html","ordinal":239,"anchor":"search-entry-239","zh":"衣片掉落后，先暂停","en":"If pieces fall away, pause first","headingZh":"衣片掉落后，先暂停","headingEn":"If pieces fall away, pause first"},{"page":"chapter-01/index.html","ordinal":240,"anchor":"search-entry-240","zh":"服装没有放在模特身上时，模拟中的重力会让它下坠。虽然可以用鼠标抓起，版片往往会皱缩，难以靠拖拽恢复平整。先按空格键暂停模拟，再重置版片。","en":"If the garment is away from the avatar, gravity makes it fall during Simulation. You can lift it with the mouse, but it may remain crumpled. Press Space to pause, then reset the pieces.","headingZh":"衣片掉落后，先暂停","headingEn":"If pieces fall away, pause first"},{"page":"chapter-01/index.html","ordinal":241,"anchor":"search-entry-241","zh":"重置 3D 版片，恢复平展","en":"Reset 3D Pattern to flatten the pieces","headingZh":"重置 3D 版片，恢复平展","headingEn":"Reset 3D Pattern to flatten the pieces"},{"page":"chapter-01/index.html","ordinal":242,"anchor":"search-entry-242","zh":"先选中要处理的版片。任何编辑都应先明确目标；在 2D 工作区框选多块版片通常更方便。","en":"First select the pieces you want to change. Editing requires a clear target; box-selecting several pieces is often easier in the 2D window.","headingZh":"重置 3D 版片，恢复平展","headingEn":"Reset 3D Pattern to flatten the pieces"},{"page":"chapter-01/index.html","ordinal":243,"anchor":"search-entry-243","zh":"鼠标移回 3D 窗口，在选中的版片上右键，选择「重置 3D 版片」。","en":"Move back to the 3D window, right-click the selected piece, and choose Reset 3D Pattern.","headingZh":"重置 3D 版片，恢复平展","headingEn":"Reset 3D Pattern to flatten the pieces"},{"page":"chapter-01/index.html","ordinal":244,"anchor":"search-entry-244","zh":"版片会恢复平展，但不一定回到原来的位置；必要时再用 Gizmo 或安排点重新放置。","en":"The pieces flatten, but may not return to their former locations. Use the Gizmo or arrangement points to position them again if needed.","headingZh":"重置 3D 版片，恢复平展","headingEn":"Reset 3D Pattern to flatten the pieces"},{"page":"chapter-01/index.html","ordinal":245,"anchor":"search-entry-245","zh":"3D 笔 · 在模特身上绘制版片","en":"3D Pen · Draw patterns on the avatar","headingZh":"3D 笔 · 在模特身上绘制版片","headingEn":"3D Pen · Draw patterns on the avatar"},{"page":"chapter-01/index.html","ordinal":246,"anchor":"search-entry-246","zh":"先在模特表面画出闭合轮廓，再将选中的区域展平为二维版片。","en":"Draw a closed outline on the avatar, then flatten the selected region into a 2D pattern.","headingZh":"3D 笔 · 在模特身上绘制版片","headingEn":"3D Pen · Draw patterns on the avatar"},{"page":"chapter-01/index.html","ordinal":247,"anchor":"search-entry-247","zh":"沿身体逐点绘制闭合轮廓","en":"Draw and close an outline on the body","headingZh":"沿身体逐点绘制闭合轮廓","headingEn":"Draw and close an outline on the body"},{"page":"chapter-01/index.html","ordinal":248,"anchor":"search-entry-248","zh":"在模特左侧工具栏长按图标，选择「3D 笔（虚拟模特）」。在 3D 窗口点击起点，再沿要制作的版片轮廓逐点点击；最后回到起点，让首尾相接，形成封闭区域。","en":"Long-press the icon beside the avatar and choose 3D Pen (Avatar). Click a starting point in the 3D window, then click successive points around the desired pattern outline. Finish by clicking the start point to close the shape.","headingZh":"沿身体逐点绘制闭合轮廓","headingEn":"Draw and close an outline on the body"},{"page":"chapter-01/index.html","ordinal":250,"anchor":"search-entry-250","zh":"展平为板片，同步到 2D 工作区","en":"Flatten the shape into a 2D pattern","headingZh":"展平为板片，同步到 2D 工作区","headingEn":"Flatten the shape into a 2D pattern"},{"page":"chapter-01/index.html","ordinal":251,"anchor":"search-entry-251","zh":"在同一工具菜单选择「展平为板片」，把鼠标移到刚画好的区域。闭合有效时，悬停的区域会变蓝；如果没有响应，先检查轮廓是否首尾相接。","en":"Choose Flatten as Pattern in the same tool menu and hover over the drawn region. A valid closed region turns blue. If nothing happens, check that the outline meets its starting point.","headingZh":"展平为板片，同步到 2D 工作区","headingEn":"Flatten the shape into a 2D pattern"},{"page":"chapter-01/index.html","ordinal":252,"anchor":"search-entry-252","zh":"点击蓝色区域，它会变为黄色，表示已选中；需要时可继续选择其他闭合区域。","en":"Click the blue region. It turns yellow to show it is selected. You may select more closed regions if needed.","headingZh":"展平为板片，同步到 2D 工作区","headingEn":"Flatten the shape into a 2D pattern"},{"page":"chapter-01/index.html","ordinal":253,"anchor":"search-entry-253","zh":"按 Enter 结束选择并展平。新板片会同时出现在 3D 模特上和 2D 工作区。","en":"Press Enter to finish selecting and flatten. The new pattern appears on the 3D avatar and in the 2D workspace.","headingZh":"展平为板片，同步到 2D 工作区","headingEn":"Flatten the shape into a 2D pattern"},{"page":"chapter-01/index.html","ordinal":255,"anchor":"search-entry-255","zh":"编辑 3D 笔 · 调整模特身上的轮廓","en":"Edit 3D Pen · Refine the outline on the avatar","headingZh":"编辑 3D 笔 · 调整模特身上的轮廓","headingEn":"Edit 3D Pen · Refine the outline on the avatar"},{"page":"chapter-01/index.html","ordinal":256,"anchor":"search-entry-256","zh":"选择左侧工具栏的「编辑 3D 笔（虚拟模特）」。在 3D 窗口点击已绘制的点或线，选中后拖动，可调整轮廓的位置和形状。录屏中依次移动了中线上的点和右侧边线，选中的线会高亮，长度数值也会随调整变化。","en":"Choose Edit 3D Pen (Avatar) on the left toolbar. Click a point or line in the 3D window and drag it to refine the outline. In the recording, points on the center edge and the right side are moved; selected lines highlight and their displayed lengths change.","headingZh":"编辑 3D 笔 · 调整模特身上的轮廓","headingEn":"Edit 3D Pen · Refine the outline on the avatar"},{"page":"chapter-01/index.html","ordinal":257,"anchor":"search-entry-257","zh":"不需要的点或线，可先选中再按 Delete 删除。删除后检查轮廓是否仍然闭合，避免后续无法「展平为板片」。","en":"To remove a point or line, select it and press Delete. Check that the outline remains closed afterward so Flatten as Pattern can still recognize the region.","headingZh":"编辑 3D 笔 · 调整模特身上的轮廓","headingEn":"Edit 3D Pen · Refine the outline on the avatar"},{"page":"chapter-01/index.html","ordinal":258,"anchor":"search-entry-258","zh":"编辑 3D 笔工具","en":"Edit 3D Pen tool","headingZh":"编辑 3D 笔 · 调整模特身上的轮廓","headingEn":"Edit 3D Pen · Refine the outline on the avatar"},{"page":"chapter-01/index.html","ordinal":259,"anchor":"search-entry-259","zh":"建立缝纫关系","en":"Create sewing relationships","headingZh":"建立缝纫关系","headingEn":"Create sewing relationships"},{"page":"chapter-01/index.html","ordinal":260,"anchor":"search-entry-260","zh":"先在 2D 工作区查看或删除缝线，再学习线缝纫与自由缝纫。检查缝线方向后，还可以用对称展开编辑半片服装，让两侧版片与缝线同步。","en":"Inspect or delete seams in 2D, then learn Segment and Free Sewing. After checking seam direction, use symmetric editing to mirror a half pattern and its sewing lines.","headingZh":"建立缝纫关系","headingEn":"Create sewing relationships"},{"page":"chapter-01/index.html","ordinal":261,"anchor":"search-entry-261","zh":"编辑缝纫线 · 查看与删除","en":"Edit Sewing · Inspect and delete seams","headingZh":"编辑缝纫线 · 查看与删除","headingEn":"Edit Sewing · Inspect and delete seams"},{"page":"chapter-01/index.html","ordinal":262,"anchor":"search-entry-262","zh":"3D 窗口里，版片之间的彩色线条表示两条边已建立缝纫关系。要查看或编辑这些缝线，请回到 2D 工作区并选择「编辑缝纫线」工具。","en":"Colored lines between pieces in the 3D window indicate that their edges are sewn together. To inspect or edit those seams, use Edit Sewing in the 2D workspace.","headingZh":"编辑缝纫线 · 查看与删除","headingEn":"Edit Sewing · Inspect and delete seams"},{"page":"chapter-01/index.html","ordinal":263,"anchor":"search-entry-263","zh":"编辑缝纫线工具","en":"Edit Sewing tool","headingZh":"编辑缝纫线 · 查看与删除","headingEn":"Edit Sewing · Inspect and delete seams"},{"page":"chapter-01/index.html","ordinal":264,"anchor":"search-entry-264","zh":"显示并检查缝线","en":"Reveal and inspect the seams","headingZh":"显示并检查缝线","headingEn":"Reveal and inspect the seams"},{"page":"chapter-01/index.html","ordinal":265,"anchor":"search-entry-265","zh":"点击「编辑缝纫线」（快捷键 B）。2D 版片边缘的缝线会显示出来；选中一条缝线，可以对照 3D 窗口里的彩色连接线，找到它缝向哪一条边。","en":"Choose Edit Sewing (B). The seam lines appear along the 2D pattern edges. Select one and compare it with the colored connection in 3D to see which edges are paired.","headingZh":"显示并检查缝线","headingEn":"Reveal and inspect the seams"},{"page":"chapter-01/index.html","ordinal":266,"anchor":"search-entry-266","zh":"删除错误的缝线","en":"Delete an incorrect seam","headingZh":"删除错误的缝线","headingEn":"Delete an incorrect seam"},{"page":"chapter-01/index.html","ordinal":267,"anchor":"search-entry-267","zh":"保持「编辑缝纫线」工具，在 2D 工作区选中要删除的缝线，再按键盘 Delete（有些键盘标为 Del）。对应的缝纫关系会消失，便可重新连接正确的边。","en":"With Edit Sewing active, select the seam in the 2D workspace and press Delete (Del on some keyboards). The sewing relationship is removed so you can connect the correct edges again.","headingZh":"删除错误的缝线","headingEn":"Delete an incorrect seam"},{"page":"chapter-01/index.html","ordinal":268,"anchor":"search-entry-268","zh":"线缝纫 · 点击两条边完成连接","en":"Segment Sewing · Click two edges to connect them","headingZh":"线缝纫 · 点击两条边完成连接","headingEn":"Segment Sewing · Click two edges to connect them"},{"page":"chapter-01/index.html","ordinal":269,"anchor":"search-entry-269","zh":"选择「线缝纫」（快捷键 N），依次点击要连接的两条版片边线。缝线一端的短标记类似剪口，提示缝纫的起始端；两边的起止方向要对应。完成后到 3D 窗口查看彩色线条的走向。","en":"Choose Segment Sewing (N), then click the two pattern edges in sequence. A small notch-like mark indicates the starting end of a seam. Match the direction on both edges and inspect the colored connection lines in 3D.","headingZh":"线缝纫 · 点击两条边完成连接","headingEn":"Segment Sewing · Click two edges to connect them"},{"page":"chapter-01/index.html","ordinal":271,"anchor":"search-entry-271","zh":"正确示范：按顺序点击两条边","en":"Correct example: click the two edges in order","headingZh":"正确示范：按顺序点击两条边","headingEn":"Correct example: click the two edges in order"},{"page":"chapter-01/index.html","ordinal":272,"anchor":"search-entry-272","zh":"先点击第一条边，再点击对应的第二条边；留意起始端标记。2D 中确认缝线关系后，转到 3D 检查彩色线条是否顺畅，再启动模拟查看服装落下的效果。","en":"Click the first edge, then its matching second edge, paying attention to the start markers. Check the seam in 2D and the colored lines in 3D, then run Simulation to see the garment settle.","headingZh":"正确示范：按顺序点击两条边","headingEn":"Correct example: click the two edges in order"},{"page":"chapter-01/index.html","ordinal":273,"anchor":"search-entry-273","zh":"错误示范：缝线交叉","en":"Incorrect example: crossed seam lines","headingZh":"错误示范：缝线交叉","headingEn":"Incorrect example: crossed seam lines"},{"page":"chapter-01/index.html","ordinal":274,"anchor":"search-entry-274","zh":"如果两条边的起止方向接反，3D 窗口里的彩色连接线会交叉。本例中看到交叉线时，应先停下来检查缝线方向，不要直接进入模拟。","en":"If the start and end directions are reversed, the colored connection lines cross in the 3D window. In this example, stop and check the seam direction before simulating.","headingZh":"错误示范：缝线交叉","headingEn":"Incorrect example: crossed seam lines"},{"page":"chapter-01/index.html","ordinal":275,"anchor":"search-entry-275","zh":"错误模拟：版片扭曲怎么办？","en":"If the garment twists during Simulation","headingZh":"错误模拟：版片扭曲怎么办？","headingEn":"If the garment twists during Simulation"},{"page":"chapter-01/index.html","ordinal":276,"anchor":"search-entry-276","zh":"沿用刚才缝反的关系启动模拟，服装会被拉扯、扭曲。按空格键暂停，删除错误缝线；如果版片已经皱缩，先重置 3D 版片，再按正确方向重缝。","en":"Run Simulation with that reversed seam and the garment pulls and twists. Press Space to pause, delete the incorrect seam, and reset crumpled 3D pieces before sewing again in the correct direction.","headingZh":"错误模拟：版片扭曲怎么办？","headingEn":"If the garment twists during Simulation"},{"page":"chapter-01/index.html","ordinal":278,"anchor":"search-entry-278","zh":"自由缝纫 · 从点到点指定范围","en":"Free Sewing · Define a seam point by point","headingZh":"自由缝纫 · 从点到点指定范围","headingEn":"Free Sewing · Define a seam point by point"},{"page":"chapter-01/index.html","ordinal":279,"anchor":"search-entry-279","zh":"「线缝纫」是依次点击两条完整边线；这里使用截图中红框标出的「M:N 自由缝纫」，从边线上的一个点开始，再指定终点，可只缝其中一段。","en":"Segment Sewing connects two whole edges by clicking them. Here, choose the highlighted M:N Free Sewing option and define a seam from a start point to an end point along each edge.","headingZh":"自由缝纫 · 从点到点指定范围","headingEn":"Free Sewing · Define a seam point by point"},{"page":"chapter-01/index.html","ordinal":281,"anchor":"search-entry-281","zh":"先选起点，再选终点","en":"Choose a start point, then an end point","headingZh":"先选起点，再选终点","headingEn":"Choose a start point, then an end point"},{"page":"chapter-01/index.html","ordinal":282,"anchor":"search-entry-282","zh":"在第一块版片的边线上点击缝合起点，再点击终点，确定第一段缝纫范围。随后到另一块版片，按对应方向选择第二段的起点与终点。","en":"Click a start point and an end point on the first pattern edge to define the first sewing span. On the matching pattern, choose the second span's start and end in the corresponding direction.","headingZh":"先选起点，再选终点","headingEn":"Choose a start point, then an end point"},{"page":"chapter-01/index.html","ordinal":283,"anchor":"search-entry-283","zh":"终点可以在线段中间","en":"The end point can be anywhere on an edge","headingZh":"终点可以在线段中间","headingEn":"The end point can be anywhere on an edge"},{"page":"chapter-01/index.html","ordinal":284,"anchor":"search-entry-284","zh":"不必缝到整条边的末端；可在线段任意位置点击，作为缝合终点。选择第二段时，线上出现的蓝色小点是按第一段长度给出的参考终点，便于对齐两侧缝合范围。","en":"The seam need not reach the end of the whole edge. Click anywhere along it to place an end point. While defining the second span, a small blue point marks the end position matching the first span's length.","headingZh":"终点可以在线段中间","headingEn":"The end point can be anywhere on an edge"},{"page":"chapter-01/index.html","ordinal":285,"anchor":"search-entry-285","zh":"对称展开编辑（缝纫线）与解除联动","en":"Symmetric Pattern with Sewing · Unlinking","headingZh":"对称展开编辑（缝纫线）与解除联动","headingEn":"Symmetric Pattern with Sewing · Unlinking"},{"page":"chapter-01/index.html","ordinal":286,"anchor":"search-entry-286","zh":"制作左右对称的服装时，可以先画好前身或后身的一半，再让 CLO 镜像展开另一半。选择带「缝纫线」的对称展开方式，后续调整半片形状或添加缝线时，另一侧也会同步。","en":"For a symmetrical garment, draft one half of the front or back pattern first, then mirror it in CLO. With the sewing-aware symmetric edit command, changes to the shape or seams on one half update the other half too.","headingZh":"对称展开编辑（缝纫线）与解除联动","headingEn":"Symmetric Pattern with Sewing · Unlinking"},{"page":"chapter-01/index.html","ordinal":287,"anchor":"search-entry-287","zh":"只画半片，再对称展开","en":"Draft half, then expand symmetrically","headingZh":"只画半片，再对称展开","headingEn":"Draft half, then expand symmetrically"},{"page":"chapter-01/index.html","ordinal":288,"anchor":"search-entry-288","zh":"选择「编辑板片」工具，在 2D 工作区选中半片的中线。","en":"Choose Edit Pattern and select the half-pattern's center line in the 2D workspace.","headingZh":"只画半片，再对称展开","headingEn":"Draft half, then expand symmetrically"},{"page":"chapter-01/index.html","ordinal":289,"anchor":"search-entry-289","zh":"右键选择「对称展开编辑（缝纫线）」。版片沿中线镜像展开，不必手动画另一半。","en":"Right-click and choose Symmetric Pattern with Sewing. CLO mirrors the piece across the center line; there is no need to draw the other half manually.","headingZh":"只画半片，再对称展开","headingEn":"Draft half, then expand symmetrically"},{"page":"chapter-01/index.html","ordinal":290,"anchor":"search-entry-290","zh":"在一侧修改轮廓或添加缝线，观察另一侧同步变化。","en":"Edit the outline or add a seam on one side and watch the other side update with it.","headingZh":"只画半片，再对称展开","headingEn":"Draft half, then expand symmetrically"},{"page":"chapter-01/index.html","ordinal":291,"anchor":"search-entry-291","zh":"中线有弧度？先删除曲线点","en":"Curved center line? Remove its curve points first","headingZh":"中线有弧度？先删除曲线点","headingEn":"Curved center line? Remove its curve points first"},{"page":"chapter-01/index.html","ordinal":292,"anchor":"search-entry-292","zh":"本例的半片中线带有曲线点，不能直接沿它对称展开。先切换到「编辑板片」工具，选中这条中线。","en":"In this example, the half-pattern's center line contains curve points, so it cannot be used for symmetric expansion yet. Choose Edit Pattern and select that center line.","headingZh":"中线有弧度？先删除曲线点","headingEn":"Curved center line? Remove its curve points first"},{"page":"chapter-01/index.html","ordinal":293,"anchor":"search-entry-293","zh":"在选中的线上右键，选择「删除曲线点」。确认中线恢复为直线。","en":"Right-click the selected line and choose Delete Curve Points. Check that the center edge is straight.","headingZh":"中线有弧度？先删除曲线点","headingEn":"Curved center line? Remove its curve points first"},{"page":"chapter-01/index.html","ordinal":294,"anchor":"search-entry-294","zh":"再右键选择「对称展开编辑（缝纫线）」，沿这条直中线展开另一半。","en":"Right-click again and choose Symmetric Pattern with Sewing to expand the other half across the straight center edge.","headingZh":"中线有弧度？先删除曲线点","headingEn":"Curved center line? Remove its curve points first"},{"page":"chapter-01/index.html","ordinal":295,"anchor":"search-entry-295","zh":"解除联动后，先看选中了多少","en":"After unlinking, check what is selected","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":296,"anchor":"search-entry-296","zh":"需要左右分别调整时，用「编辑板片」工具选中版片，右键选择「解除联动」。之后单侧修改不再同步到另一侧。","en":"When the two sides need different edits, select the pattern with Edit Pattern, right-click, and choose Unlink. Edits on one side no longer mirror to the other.","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":297,"anchor":"search-entry-297","zh":"录屏中的前身片：解除联动后可单独选中一侧并删除，保留另一半。","en":"In the recorded front pattern, one side can be selected and deleted after unlinking, leaving the other half.","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":298,"anchor":"search-entry-298","zh":"录屏中的后身片：点击一侧时两边一起高亮，说明当前仍选中整片；此时按 Delete 会把两边一起删除。","en":"In the recorded back pattern, clicking one side highlights both, so the whole piece is selected. Pressing Delete at that point removes both sides.","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":299,"anchor":"search-entry-299","zh":"解除联动只取消同步编辑，不保证自动把一整片切成两块。删除前一定先看高亮范围。","en":"Unlinking stops mirrored editing, but does not necessarily split one pattern into two pieces. Always check the highlighted area before deleting.","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":300,"anchor":"search-entry-300","zh":"课堂练习｜一片式裁剪","en":"Class project | One-piece cutting","headingZh":"课堂练习｜一片式裁剪","headingEn":"Class project | One-piece cutting"},{"page":"chapter-01/index.html","ordinal":301,"anchor":"search-entry-301","zh":"图文参考：从平面到服装","en":"Image references: from flat pattern to garment","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":302,"anchor":"search-entry-302","zh":"先看平面纸样与折叠示意，再看成衣的造型。下面四张是参考资料，用来观察一片式裁剪如何从平面形成空间；它们不是本课要逐尺寸复刻的纸样。点击图片可放大查看。","en":"Start with the flat patterns and folding diagrams, then compare the finished silhouettes. These four references show ways a one-piece cut can become a three-dimensional garment; they are not measurements to reproduce in this exercise. Select an image to enlarge it.","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":303,"anchor":"search-entry-303","zh":"01 · 一片布如何折成服装","en":"01 · How one piece folds into a garment","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":304,"anchor":"search-entry-304","zh":"02 · 对照裁切、折叠与缝合位置","en":"02 · Compare cutting, folding, and seams","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":305,"anchor":"search-entry-305","zh":"03 · 观察开口与侧边如何形成廓形","en":"03 · See how openings and sides shape the silhouette","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":306,"anchor":"search-entry-306","zh":"04 · 比较平面形状与穿着后的体积","en":"04 · Compare the flat shape with worn volume","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":309,"anchor":"search-entry-309","zh":"用已学过的矩形、内部形状、圆形和对称展开工具，自由探索平面裁片的组合。这次先完成裁片准备：一块连续的大身片，加上前、后两块圆形裁片；后续再考虑连接和模拟。","en":"Explore a garment layout using Rectangle, Internal Shape, Ellipse, and Symmetric Pattern. This stage prepares one continuous body panel plus two circular front/back pieces; sewing and simulation come later.","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":310,"anchor":"search-entry-310","zh":"先建立大身片和圆形裁片","en":"Create the body and circular pieces","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":311,"anchor":"search-entry-311","zh":"在 2D 工作区用「矩形」先画大身片的一半，让内侧边线落在模特剪影的中线附近。","en":"Use Rectangle in the 2D workspace to draw half of the body panel, with its inner edge near the avatar silhouette's center line.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":312,"anchor":"search-entry-312","zh":"选中中线，右键选择「对称展开编辑（缝纫线）」，得到完整、左右对称的大身片。","en":"Select the center edge, right-click, and choose Symmetric Pattern with Sewing to expand it into a full, symmetrical body panel.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":313,"anchor":"search-entry-313","zh":"大身片需要留出双臂位置：在片内绘制两个椭圆形内部轮廓，先确定袖口位置。此时红色轮廓只是内部线，尚未切成洞。","en":"Plan space for both arms by drawing two elliptical internal outlines on the body panel. These red outlines are internal lines at this stage, not openings yet.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":314,"anchor":"search-entry-314","zh":"再用「圆形」工具创建前、后两块圆形裁片，放在大身片两侧；录屏中它们显示为椭圆。最后切换 3D 视角，检查三块裁片的位置。","en":"Use Ellipse to create the front and back circular pieces and place them on either side of the body panel. They appear oval in the recording. Finally, check their placement in 3D.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":315,"anchor":"search-entry-315","zh":"自由练习：改变大身片的宽度、袖口间距或圆形裁片的比例。每改一次，观察 2D 与 3D 的对应关系；这一阶段先不要求缝合成衣。","en":"Explore: change the body panel width, armhole spacing, or the proportions of the circular pieces. After each edit, compare the 2D and 3D views. Sewing the garment is not required at this stage.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":316,"anchor":"search-entry-316","zh":"大身片与袖口内部线","en":"Body panel with internal armhole outlines","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":317,"anchor":"search-entry-317","zh":"加入前、后圆形裁片","en":"Add front and back circular pieces","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":319,"anchor":"search-entry-319","zh":"接下来：开一个小领口","en":"Next: make a small neckline opening","headingZh":"接下来：开一个小领口","headingEn":"Next: make a small neckline opening"},{"page":"chapter-01/index.html","ordinal":320,"anchor":"search-entry-320","zh":"先选中大身片，用「编辑板片」右键解除联动。领口位于中线附近；若左右仍联动，同一位置的操作可能重叠。","en":"Select the body panel and unlink its symmetric editing with Edit Pattern. The neckline sits near the center line, where mirrored edits could overlap.","headingZh":"接下来：开一个小领口","headingEn":"Next: make a small neckline opening"},{"page":"chapter-01/index.html","ordinal":321,"anchor":"search-entry-321","zh":"在大身片内部、模特颈部对应的位置画一个小圆形内部轮廓。选中它，右键「转化为洞」；也可用「切断」分出内侧裁片，再移除内侧裁片。","en":"Draw a small circular internal shape where the avatar's neck meets the body panel. Select it and choose Convert to Hole, or Cut it and remove the separated inner piece.","headingZh":"接下来：开一个小领口","headingEn":"Next: make a small neckline opening"},{"page":"chapter-01/index.html","ordinal":322,"anchor":"search-entry-322","zh":"本练习暂不考虑拉链或纽扣开口，因此领口只要能让模特颈部通过即可，不必开得太大。回到 3D 窗口观察位置，用 Gizmo 稍作调整。","en":"This exercise does not yet plan a zipper or button opening, so the neckline only needs to clear the avatar's neck. Check it in 3D and adjust the panel slightly with the Gizmo.","headingZh":"接下来：开一个小领口","headingEn":"Next: make a small neckline opening"},{"page":"chapter-01/index.html","ordinal":324,"anchor":"search-entry-324","zh":"连接缝线，再开袖口","en":"Sew the pieces, then open the armholes","headingZh":"连接缝线，再开袖口","headingEn":"Sew the pieces, then open the armholes"},{"page":"chapter-01/index.html","ordinal":325,"anchor":"search-entry-325","zh":"使用「自由缝纫」，在大身片边线上依次确定起点和终点，再沿对应圆形裁片的弧边选择起点、终点。前后两侧分别建立缝纫关系。","en":"Use Free Sewing to choose a start and end point on the body panel edge, then a corresponding start and end along the circular piece's curved edge. Repeat for the front and back.","headingZh":"连接缝线，再开袖口","headingEn":"Sew the pieces, then open the armholes"},{"page":"chapter-01/index.html","ordinal":326,"anchor":"search-entry-326","zh":"这次允许两条缝合边长度不同，目的是在模拟时尝试抽褶。重点检查 3D 窗口的彩色连接线：起止顺序应一致，线条不要交叉。","en":"The sewn lengths may differ in this exercise to explore gathers during simulation. Check the colored connection lines in 3D: their start/end order should match and the lines should not cross.","headingZh":"连接缝线，再开袖口","headingEn":"Sew the pieces, then open the armholes"},{"page":"chapter-01/index.html","ordinal":327,"anchor":"search-entry-327","zh":"大身片上的两个红色椭圆目前只是内部线，布料仍挡住手臂。逐个选中它们，右键「转化为洞」；也可以「切断」后移走内侧小裁片。确认 2D 中能透出背景网格、3D 中也看得到开口，再检查开口是否对准模特手臂。","en":"The two red ellipses are still internal lines, so the cloth blocks the arms. Select each one and choose Convert to Hole, or Cut and move away the small inner piece. Confirm that the 2D grid shows through and that each 3D opening lines up with an arm.","headingZh":"连接缝线，再开袖口","headingEn":"Sew the pieces, then open the armholes"},{"page":"chapter-01/index.html","ordinal":328,"anchor":"search-entry-328","zh":"开始模拟，整理穿过袖口的手臂","en":"Simulate and guide the arms through the openings","headingZh":"开始模拟，整理穿过袖口的手臂","headingEn":"Simulate and guide the arms through the openings"},{"page":"chapter-01/index.html","ordinal":329,"anchor":"search-entry-329","zh":"缝线方向和三个开口检查无误后，按空格键开始模拟。版片落到模特身上，观察面料是否与身体相交。","en":"Once the sewing direction and three openings look correct, press Space to start Simulation. Watch the pieces settle and check whether the cloth intersects the avatar.","headingZh":"开始模拟，整理穿过袖口的手臂","headingEn":"Simulate and guide the arms through the openings"},{"page":"chapter-01/index.html","ordinal":330,"anchor":"search-entry-330","zh":"如果大身片太软、容易穿进模特身体，再按空格暂停。选中大身片，右键选择「硬化」；这是临时加硬，方便把版片撑开、调整位置，之后也可以右键解除硬化。","en":"If the body panel is too soft and intersects the avatar, press Space again to pause. Select the body panel, right-click, and choose Strengthen. This temporarily stiffens it for easier handling and can be undone later.","headingZh":"开始模拟，整理穿过袖口的手臂","headingEn":"Simulate and guide the arms through the openings"},{"page":"chapter-01/index.html","ordinal":331,"anchor":"search-entry-331","zh":"重新按空格继续模拟。若手臂仍被布料挡住，在 3D 窗口耐心地拖动袖口边缘，一点点引导布料绕过手臂，让手从开口穿出。需要时随时暂停再调整。","en":"Press Space to resume. If an arm is still trapped by the cloth, gently drag the armhole edge in 3D and guide the fabric around the arm until the hand emerges. Pause and adjust whenever needed.","headingZh":"开始模拟，整理穿过袖口的手臂","headingEn":"Simulate and guide the arms through the openings"},{"page":"chapter-01/index.html","ordinal":333,"anchor":"search-entry-333","zh":"用眼睛判断布量，再圆顺大身片四角","en":"Judge the volume by eye, then smooth the corners","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":334,"anchor":"search-entry-334","zh":"这一节先不以固定尺寸限制创作。旋转 3D 视角，看布料堆叠与褶量是否合心意；如果想要更多垂褶，暂停模拟，在 2D 放大相应裁片，再继续观察。","en":"Explore without a fixed target measurement. Orbit the 3D view and judge the fabric volume and gathers by eye. For more drape, pause Simulation, enlarge the relevant pattern in 2D, then inspect again.","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":335,"anchor":"search-entry-335","zh":"想让大身片四角更柔和时，长按「编辑板片」工具，选择「生成圆顺曲线」。","en":"To soften the body panel corners, long-press Edit Pattern and choose Create Smooth Curve.","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":336,"anchor":"search-entry-336","zh":"把鼠标放在角点上，按住并拖动，让相邻两条边过渡为圆弧。观察 3D 外轮廓，按喜欢的弧度调整。","en":"Hover over a corner, then click and drag to round the transition between its two adjoining edges. Judge the curve in the 3D silhouette.","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":337,"anchor":"search-entry-337","zh":"此前已经解除对称联动，左右角不会自动同步；需要分别操作。调整完再按空格模拟，检查新的垂坠与袖口位置。","en":"Because symmetric editing was unlinked earlier, changes to one side will not mirror automatically. Round the corners on both sides, then press Space to simulate and inspect the new drape and armholes.","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":340,"anchor":"search-entry-340","zh":"再缝合后片两侧","en":"Sew the back panel along both sides","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":341,"anchor":"search-entry-341","zh":"从背面再看一次造型：如果把后片的两侧与大身片相连，布料会更完整地围住身体，像一件轻盈的万圣节幽灵装。这里最容易出错的是两条缝线的起止顺序。","en":"Check the silhouette from behind. Joining both sides of the back panel to the body panel wraps the fabric around the avatar, giving it a playful ghost-like shape. Pay close attention to the start and end order of each seam.","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":342,"anchor":"search-entry-342","zh":"先在 3D 窗口点击要缝的板片或边缘，留意出现的蓝色高亮点；2D 工作区对应的板片上也会显示相应位置。对照两边，确认这条边的前后与起点、终点。","en":"Click the piece or edge you plan to sew in 3D and note the blue highlighted point. Its corresponding position appears on the 2D pattern. Use both views to identify the matching edge and its start and end.","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":343,"anchor":"search-entry-343","zh":"选择「自由缝纫」，按相同方向依次指定第一条边的起点、终点，再指定对应边的起点、终点。缝第二条边时，边操作边看 3D：湖蓝色高亮的是当前正在指定的缝纫边，借它检查是否选对侧边、顺序是否一致。","en":"Choose Free Sewing. Set the start and end on one edge, then the matching start and end on the other edge in the same direction. While sewing the second side, watch the cyan-highlighted active edge in 3D to confirm the edge and seam direction.","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":344,"anchor":"search-entry-344","zh":"左右两侧都完成后，再看 3D 的连接线是否交叉；若方向有误，先调整缝线。最后按空格模拟，观察后片与大身片合拢后的垂坠。","en":"Repeat on both sides. Check that the 3D connection lines do not cross, correcting any reversed seam before pressing Space to simulate and inspect the drape of the joined panels.","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":345,"anchor":"search-entry-345","zh":"官方资料与图片说明","en":"Official references & image notes","headingZh":"官方资料与图片说明","headingEn":"Official references & image notes"},{"page":"chapter-01/index.html","ordinal":346,"anchor":"search-entry-346","zh":"操作说明参考 CLO 官方帮助中心。二维工具卡片与三维 Gizmo、模块库、模拟课程使用实机截图和课堂录屏；缝纫和 3D 笔课程使用本机 CLO 2025.0.128 的工具截图与录屏。","en":"Instructions reference the CLO Help Center. The 2D lessons, Gizmo, Module Library, and Simulation use actual captures and classroom recordings. The sewing and 3D Pen lessons use CLO 2025.0.128 tool captures and recordings.","headingZh":"官方资料与图片说明","headingEn":"Official references & image notes"},{"page":"chapter-01/index.html","ordinal":347,"anchor":"search-entry-347","zh":"关于 CLO3D","en":"About CLO3D","headingZh":"关于 CLO3D","headingEn":"About CLO3D"},{"page":"chapter-01/index.html","ordinal":348,"anchor":"search-entry-348","zh":"想查看完整的图文讲义、工具对照表和资料链接？点此单独阅读，读完可返回本章操作教程。","en":"Open the complete illustrated notes, tool tables, and reference links in a separate page. You can return to this lesson at any time.","headingZh":"关于 CLO3D","headingEn":"About CLO3D"},{"page":"chapter-01/about-clo3d.html","ordinal":3,"anchor":"search-entry-3","zh":"第一章 · 详细图文讲义","en":"Chapter 01 · Complete Illustrated Notes","headingZh":"第一章 · 详细图文讲义","headingEn":"Chapter 01 · Complete Illustrated Notes"},{"page":"chapter-01/about-clo3d.html","ordinal":4,"anchor":"search-entry-4","zh":"补充收录此前 CLO3D BEGINNER’S GUIDE 的讲解、工具表格、课堂英文表达和配图参考。各章节的 CLO 截图均已存为本地资源，并与对应讲解配对。","en":"Expanded explanations, tool tables, classroom phrases and image references from the original beginner's guide. All chapter screenshots are stored locally and paired with the relevant lesson text.","headingZh":"第一章 · 详细图文讲义","headingEn":"Chapter 01 · Complete Illustrated Notes"},{"page":"chapter-01/about-clo3d.html","ordinal":5,"anchor":"search-entry-5","zh":"软件界面详解","en":"Software Interface","headingZh":"软件界面详解","headingEn":"Software Interface"},{"page":"chapter-01/about-clo3d.html","ordinal":6,"anchor":"search-entry-6","zh":"CLO3D 可同时显示二维版片与三维服装。2D Pattern Window 用于绘制和编辑版片，3D Garment Window 用于检查穿着、视角和模拟效果。Library 提供资源，Object Browser 管理对象，而 Property Editor 用来调整选中对象的参数。","en":"CLO3D displays 2D patterns and 3D garments side by side. The 2D Pattern Window creates and edits patterns, while the 3D Garment Window displays fit and simulation. Library contains assets, Object Browser organizes objects, and Property Editor modifies the selected object.","headingZh":"软件界面详解","headingEn":"Software Interface"},{"page":"chapter-01/about-clo3d.html","ordinal":7,"anchor":"search-entry-7","zh":"Object Browser 与 Property Editor 的区别尤为重要：前者主要用于查找和选取对象，后者用于编辑它的属性。单击不同面料，观察 Property Editor 中的参数变化。","en":"A key distinction is that Object Browser selects and manages objects, while Property Editor changes their settings. Select different fabrics and observe the available properties.","headingZh":"软件界面详解","headingEn":"Software Interface"},{"page":"chapter-01/about-clo3d.html","ordinal":20,"anchor":"search-entry-20","zh":"二维版片工具操作","en":"Working with 2D Tools","headingZh":"二维版片工具操作","headingEn":"Working with 2D Tools"},{"page":"chapter-01/about-clo3d.html","ordinal":21,"anchor":"search-entry-21","zh":"先从 Transform Pattern 和 Edit Pattern 开始。Transform Pattern 用于调整整片版片的位置、旋转或缩放，而 Edit Pattern 用于改变点、边线和轮廓；不要为了修改领口弧度而缩放整块衣片。Rectangle 适合规则形状，Polygon 适合自由轮廓，Ellipse 适合圆形或椭圆形。","en":"Begin with Transform Pattern and Edit Pattern. Transform Pattern moves, rotates or scales an entire piece; Edit Pattern modifies points, segments and contours. Do not resize an entire pattern to adjust a neckline. Rectangle makes regular shapes, Polygon custom contours, and Ellipse circular shapes.","headingZh":"二维版片工具操作","headingEn":"Working with 2D Tools"},{"page":"chapter-01/about-clo3d.html","ordinal":22,"anchor":"search-entry-22","zh":"还应认识 Add Point / Split Line（添加点/分割线）、Edit Curvature（编辑曲率）和 Internal Line（内部线）。练习时先画一个矩形，再通过编辑点和曲线将它改为不规则轮廓。","en":"Also recognize Add Point / Split Line, Edit Curvature and Internal Line. Practice by drawing a rectangle, then modifying its points and curved edges.","headingZh":"二维版片工具操作","headingEn":"Working with 2D Tools"},{"page":"chapter-01/about-clo3d.html","ordinal":37,"anchor":"search-entry-37","zh":"三维选择、安排与模拟","en":"3D Placement & Simulation","headingZh":"三维选择、安排与模拟","headingEn":"3D Placement & Simulation"},{"page":"chapter-01/about-clo3d.html","ordinal":38,"anchor":"search-entry-38","zh":"在三维空间中，Select / Move 用于选择并调整版片，Gizmo 是控制移动与旋转方向的操纵器，Arrangement 用于将版片安排在模特附近。学生必须区分 Move the View（移动观察视角）和 Move the Object（改变对象位置）。","en":"In 3D, Select / Move picks and positions patterns, Gizmo controls movement and rotation directions, and Arrangement places pieces near an avatar. Students should distinguish Move the View from Move the Object.","headingZh":"三维选择、安排与模拟","headingEn":"3D Placement & Simulation"},{"page":"chapter-01/about-clo3d.html","ordinal":39,"anchor":"search-entry-39","zh":"Simulation 根据版片、缝纫、重力与碰撞计算布料垂坠。启动前先确认版片位置与缝合关系，否则版片可能掉落。不同版本的按钮与快捷键可能略有不同。","en":"Simulation calculates drape using patterns, sewing, gravity and collision. Before starting it, check placement and sewing; unconnected pieces may fall. Button locations and shortcuts can vary by version.","headingZh":"三维选择、安排与模拟","headingEn":"3D Placement & Simulation"},{"page":"chapter-01/about-clo3d.html","ordinal":50,"anchor":"search-entry-50","zh":"缝纫工具操作","en":"Connecting Pattern Pieces","headingZh":"缝纫工具操作","headingEn":"Connecting Pattern Pieces"},{"page":"chapter-01/about-clo3d.html","ordinal":51,"anchor":"search-entry-51","zh":"Segment Sewing（线段缝纫）将两块版片的完整边线连接；先单击第一条线段，再单击第二条线段创建缝纫关系。Free Sewing（自由缝纫）允许自行指定缝合的起始点与终点，适合局部缝合需求。","en":"Segment Sewing connects two complete pattern edges: click one segment, then the other. Free Sewing lets you choose custom start and end points for localized stitching.","headingZh":"缝纫工具操作","headingEn":"Connecting Pattern Pieces"},{"page":"chapter-01/about-clo3d.html","ordinal":52,"anchor":"search-entry-52","zh":"缝纫在二维版片之间建立连接关系，随后 Simulation 才会依据这些连接来计算布料。对于新手，建议先练习两块简单矩形布料的边缘缝合。","en":"Sewing creates relationships between 2D pattern pieces; Simulation then uses those relationships to calculate their 3D behavior. Beginners can practice on two simple rectangular pieces.","headingZh":"缝纫工具操作","headingEn":"Connecting Pattern Pieces"},{"page":"chapter-01/about-clo3d.html","ordinal":55,"anchor":"search-entry-55","zh":"官方教程与动态演示链接","en":"Official Guides & Motion Demonstrations","headingZh":"官方教程与动态演示链接","headingEn":"Official Guides & Motion Demonstrations"},{"page":"chapter-01/about-clo3d.html","ordinal":56,"anchor":"search-entry-56","zh":"上方四段鼠标与视角演示已使用课堂实录视频。下方链接可打开官方资料继续学习；后续课程可再加入版片编辑、缝纫与模拟的录屏。","en":"The four mouse and view demonstrations above are classroom recordings. The links below open official references for further study. Future lessons can add recordings for pattern editing, sewing, and simulation.","headingZh":"官方教程与动态演示链接","headingEn":"Official Guides & Motion Demonstrations"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":2,"anchor":"search-entry-2","zh":"重置 3D 版片","en":"Reset 3D Pattern","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":3,"anchor":"search-entry-3","zh":"模拟出错后，先按空格键暂停。重置可让选中的版片恢复平展，但不保证回到原来的空间位置。","en":"If Simulation goes wrong, press Space to pause. Resetting flattens the selected pieces, but may not restore their former positions.","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":4,"anchor":"search-entry-4","zh":"在 2D 工作区框选需要复原的版片。编辑前先选中目标。","en":"Box-select the pieces to restore in the 2D workspace. Always select your target before editing.","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":5,"anchor":"search-entry-5","zh":"鼠标移到 3D 窗口，在选中的版片上右键，选择「重置 3D 版片」。","en":"Move to the 3D window, right-click the selected piece, and choose Reset 3D Pattern.","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":6,"anchor":"search-entry-6","zh":"检查版片是否恢复平展；必要时用 Gizmo 或安排点重新放置，再重新检查缝线方向。","en":"Check that the pieces are flat. Reposition them with the Gizmo or arrangement points if needed, then check the seam directions again.","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"shirt-lesson/index.html","ordinal":4,"anchor":"search-entry-4","zh":"从男士基础版开始，把胸省与肩省的量转移到领口和袖窿，再像用硫酸纸描图一样，勾勒出无省道上衣板。跟着录屏理解切开、旋转与描线的关系，设计自己的衬衫版型。","en":"Start with a men's basic block, transfer the chest and shoulder dart intake to the neckline and armhole, then trace a dartless bodice block as if using tracing paper. Follow the recordings to connect cutting, rotating, and tracing with your own shirt design.","headingZh":"男士衬衫版型设计","headingEn":"Men's shirt pattern design"},{"page":"shirt-lesson/index.html","ordinal":16,"anchor":"search-entry-16","zh":"准备版片与模特","en":"Prepare the pattern and avatar","headingZh":"男士衬衫版型设计","headingEn":"Men's shirt pattern design"},{"page":"shirt-lesson/index.html","ordinal":17,"anchor":"search-entry-17","zh":"从男士基础版开始","en":"Start with the men's basic block","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":18,"anchor":"search-entry-18","zh":"打开课程文件，里面已经有男士基础版片。先加入虚拟模特，再把版片放到模特身上对应的位置，为接下来的版型调整建立 2D 与 3D 的对应关系。","en":"Open the course file containing the men's basic pattern pieces. Add an avatar, then arrange each piece near its corresponding position on the body so the 2D pattern and 3D placement are easy to compare.","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":19,"anchor":"search-entry-19","zh":"在「文件」菜单打开已有的男士基础版。","en":"Open the prepared men's basic block from the File menu.","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":20,"anchor":"search-entry-20","zh":"加入虚拟模特；选中板片，在 3D 窗口将它放到相应身体区域。录屏中演示了前片的安排。","en":"Add an avatar. Select a piece and place it near the matching body area in the 3D window. The recording demonstrates positioning a front piece.","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":21,"anchor":"search-entry-21","zh":"操作视频 · 打开文件、加入模特并安放板片","en":"Demonstration · Open the file, add the avatar, and arrange a piece","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":22,"anchor":"search-entry-22","zh":"接下来，开始改板片","en":"Next, reshape the pattern","headingZh":"接下来，开始改板片","headingEn":"Next, reshape the pattern"},{"page":"shirt-lesson/index.html","ordinal":23,"anchor":"search-entry-23","zh":"这一步就是版型设计。录屏里的数值只是示范，不必完全照抄；理解松量从哪里收起、又在哪里打开，就能按同样的逻辑设计自己想要的衬衫。","en":"This is the pattern-design stage. The values shown in the recordings are examples, not fixed measurements. Once you understand where ease closes and where it opens, you can use the same logic to shape your own shirt.","headingZh":"接下来，开始改板片","headingEn":"Next, reshape the pattern"},{"page":"shirt-lesson/index.html","ordinal":24,"anchor":"search-entry-24","zh":"胸省 → 领口","en":"Chest dart → Neckline","headingZh":"接下来，开始改板片","headingEn":"Next, reshape the pattern"},{"page":"shirt-lesson/index.html","ordinal":25,"anchor":"search-entry-25","zh":"切出可旋转的小板片","en":"Cut a small piece that can rotate","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":26,"anchor":"search-entry-26","zh":"希望领口多一点松量，就先从胸省省尖向领口切开，让这一块前片可以单独旋转。","en":"To add some ease at the neckline, cut from the chest dart tip to the neckline so this section of the front pattern can rotate independently.","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":27,"anchor":"search-entry-27","zh":"按 G 使用「半片内部线」，从胸省省尖画到领口；双击结束线段。","en":"Press G for Half Pattern Internal Line. Draw from the chest dart tip to the neckline, then double-click to finish the line.","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":28,"anchor":"search-entry-28","zh":"选中这条内部线，右键选择「切断」。切开后得到一块可单独操作的小板片。","en":"Select the internal line, right-click, and choose Cut. The cut creates a small piece you can move separately.","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":29,"anchor":"search-entry-29","zh":"操作视频 · 画内部线并切断","en":"Demonstration · Draw an internal line and cut","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":30,"anchor":"search-entry-30","zh":"关闭一处 · 打开另一处","en":"Close one area · Open another","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":31,"anchor":"search-entry-31","zh":"合胸省，打开领口","en":"Close the chest dart and open the neckline","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":32,"anchor":"search-entry-32","zh":"让原来胸省的两侧在省尖处对齐，再以省尖为中心旋转小板片。胸省收小的量，会转移到领口形成新的开口。","en":"Align the two sides of the original chest dart at its tip, then rotate the small piece around that point. As the chest dart becomes smaller, an opening appears at the neckline.","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":33,"anchor":"search-entry-33","zh":"将原来的两个省道点尽量重合；拖动时按 Ctrl（Mac 按 Command）可细调位置。","en":"Bring the original dart points together. Hold Ctrl (Command on Mac) while dragging for finer adjustment.","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":34,"anchor":"search-entry-34","zh":"双击旋转中心，将它移到省尖，再旋转板片。观察领口打开的宽度，按想要的松量决定旋转角度，无须照抄录屏数值。","en":"Double-click the rotation center and move it to the dart tip, then rotate the piece. Choose the angle by the neckline opening you want rather than copying the number in the recording.","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":35,"anchor":"search-entry-35","zh":"操作视频 · 重设旋转中心并打开领口","en":"Demonstration · Move the pivot and open the neckline","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":36,"anchor":"search-entry-36","zh":"肩省 → 领口与袖窿","en":"Shoulder dart → Neckline & armhole","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":37,"anchor":"search-entry-37","zh":"为肩省转移做两处切口","en":"Make two cuts from the shoulder dart","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":38,"anchor":"search-entry-38","zh":"前片的袖窿也需要松量。和前一步同理，以肩省省尖为起点，分别向领口与袖窿画内部线，再把两条线切开。","en":"The front armhole also needs ease. As before, start at the shoulder dart tip. Draw one internal line to the neckline and another to the armhole, then cut along both lines.","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":39,"anchor":"search-entry-39","zh":"按 G，从肩省省尖向领口画线；再从同一省尖向袖窿画线。每条线双击结束。","en":"Press G and draw a line from the shoulder dart tip to the neckline, then another from the same tip to the armhole. Double-click to finish each line.","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":40,"anchor":"search-entry-40","zh":"分别选中两条内部线，右键「切断」，得到可围绕省尖旋转的小板片。","en":"Select each internal line and use Cut from the right-click menu. This produces pieces that can rotate around the dart tip.","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":41,"anchor":"search-entry-41","zh":"操作视频 · 肩省画线与切断","en":"Demonstration · Draw and cut from the shoulder dart","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":42,"anchor":"search-entry-42","zh":"把松量放到想要的位置","en":"Place the ease where you want it","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":43,"anchor":"search-entry-43","zh":"先开领口，再转到袖窿","en":"Open the neckline, then the armhole","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":44,"anchor":"search-entry-44","zh":"把切出的板片重新以肩省省尖对齐。先给领口留一点开口，再旋转左侧小板片，关闭肩省，让更多松量转移到袖窿。","en":"Align the cut pieces again at the shoulder dart tip. Open the neckline slightly first, then rotate the left piece to close the shoulder dart and transfer more ease to the armhole.","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":45,"anchor":"search-entry-45","zh":"对齐省尖，先旋转靠领口的小板片，留出少量领口松量。","en":"Align the dart tips and rotate the neckline-side piece to leave a small neckline opening.","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":46,"anchor":"search-entry-46","zh":"再旋转左侧小板片，使肩省闭合，同时观察袖窿处打开的量。按希望的造型调整，不必追求录屏里的角度。","en":"Rotate the left piece to close the shoulder dart while watching the armhole opening. Adjust it for the shape you want rather than matching the recorded angle.","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":47,"anchor":"search-entry-47","zh":"版型小贴士","en":"Pattern tip","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":48,"anchor":"search-entry-48","zh":"一般会在前片领口留出一些松量；后片领口可视设计需要决定是否增加。避免只给后片领口加松量、前片却完全不加。","en":"The front neckline usually receives some ease. Adding ease to the back neckline depends on the design. Avoid adding ease only at the back while leaving the front neckline unchanged.","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":49,"anchor":"search-entry-49","zh":"操作视频 · 关闭肩省并调整袖窿松量","en":"Demonstration · Close the shoulder dart and adjust armhole ease","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":50,"anchor":"search-entry-50","zh":"像硫酸纸一样描版","en":"Trace the pattern like tracing paper","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":51,"anchor":"search-entry-51","zh":"先勾勒直线轮廓","en":"Trace the straight edges first","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":52,"anchor":"search-entry-52","zh":"省道的量已经分配到领口和袖窿。现在在原板片上盖一片矩形，把调整后的轮廓转描到这片新板片上。","en":"The dart intake has been distributed to the neckline and armhole. Place a rectangle over the original pieces and trace their adjusted outlines onto this new pattern piece.","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":53,"anchor":"search-entry-53","zh":"按 S 创建矩形，让矩形覆盖要描绘的板片；从左上角的「服装渲染类型」菜单选择「半透明表面」，使下面的原板片可见。","en":"Press S to create a rectangle over the pieces you want to trace. From Garment Rendering Type at the upper left, choose Semi-Transparent Surface so the original pieces remain visible underneath.","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":54,"anchor":"search-entry-54","zh":"按 I 使用图示工具，依次点击原板片上相连、未被打断的直线边；按 Enter 结束。新矩形上会出现红色内部线。","en":"Press I to use the tool shown here. Click the connected, unbroken straight edges of the original pattern in sequence, then press Enter. Red internal lines appear on the new rectangle.","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":55,"anchor":"search-entry-55","zh":"操作视频 · 用半透明矩形描直线","en":"Demonstration · Trace straight edges on a semi-transparent rectangle","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":56,"anchor":"search-entry-56","zh":"补齐领口与袖窿","en":"Complete the neckline and armhole","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":57,"anchor":"search-entry-57","zh":"画曲线，完成无省道上衣板","en":"Draw the curves to finish the dartless block","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":58,"anchor":"search-entry-58","zh":"直线确定后，用「内部多边形／线」补画领口、袖窿等曲线。点不用很多，重点是让线条顺着原板片的弧度走。","en":"Once the straight edges are in place, use Internal Polygon/Line to add the neckline, armhole, and other curves. You need only a few points; focus on following the original pattern's smooth contours.","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":59,"anchor":"search-entry-59","zh":"按 G 选择「内部多边形／线」，沿曲线依次落点；在需要弧度的位置按住鼠标拖动，调整曲线方向。","en":"Press G for Internal Polygon/Line. Add points along each curve; click and drag where the line needs a bend to shape its direction.","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":60,"anchor":"search-entry-60","zh":"视图不够用时，按住鼠标滚轮拖动画布。曲线画完按 Enter 收尾，检查前后片轮廓是否顺畅衔接。","en":"Hold the middle mouse button and drag to pan the canvas when you need more room. Press Enter to finish each curve, then check that the front and back outlines connect smoothly.","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":61,"anchor":"search-entry-61","zh":"操作视频 · 描绘曲线并完成轮廓","en":"Demonstration · Draw the curves and complete the outline","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":62,"anchor":"search-entry-62","zh":"这一步的结果","en":"Result of this step","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":64,"anchor":"search-entry-64","zh":"从切开、合省和旋转，到在半透明板片上描出新轮廓，我们已经得到一版无省道上衣板。接下来可以在这个基础上继续设计衬衫的细节。","en":"From cutting, closing, and rotating darts to tracing the new outline on a semi-transparent piece, you now have a dartless bodice block to develop into your shirt design.","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"}];
